from rcb_client import Robot
import numpy as np
from PIL import Image
r=Robot(); o=r.get_obs(cameras=[],video='none'); now=np.array(o.meta['proprio']['now']); cur=now[7:14].copy(); qdown=np.array([0.,1.,0.,0.]); print('before',cur)

def P(x,y,z,q=qdown): return np.array([x,y,z,*q],float)
def rows_for(wps):
 global cur
 out=[]
 for w in wps:
  w=np.array(w,float); n=max(1,int(np.ceil(np.linalg.norm(w[:3]-cur[:3])/.007)))
  for a in np.linspace(1/n,1,n):
   p=cur.copy(); p[:3]=cur[:3]+a*(w[:3]-cur[:3]); p[3:]=w[3:]; out.append(p)
  cur=w
 return np.array(out,np.float32)
way=[P(-.10,0,.28),P(-.065,.1775,.10),P(-.065,.1775,.022),P(-.065,.1775,.10),P(-.16,-.1856,.10),P(-.16,-.1856,.015),P(-.04,-.1856,.015),P(-.04,-.1856,.10),P(.05,.10,.28)]
a=rows_for(way)
print('IK endpoints')
seed=now[:7]
for p in way: print(p[:3],r.ik({'tip':p},seed=seed)['ok'])
for j in range(0,len(a),190):
 res=r.submit('ee_pose',a[j:j+190],dt=.05,video='none',note='practice-dark-test'); print('chunk',res.meta['executed_rows'],res.meta['control_steps_chunk'],'fail',sum(x['ik_failures'] for x in res.meta['plan']),res.meta['time_left_s'])
print('status',r.status())
o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],video='none')
for c,img in o.last.items(): Image.fromarray(img).save('/app/output/darktest_'+c+'.png')
